// Private host-boundary probes: custom source identity is rejected before any
// optional API lookup, world access, filesystem open/read or producer demand.
// The actual custom Base remains the ordinary checker's responsibility.
const customText=info.sourceText+'\n# phase65 custom Base demand guard\n',customInfo={...info,baseSha256:hash(Buffer.from(customText)),sourceText:customText};
assert.notEqual(customInfo.baseSha256,info.baseSha256);
for(const presence of ['valid','corrupt','absent'])check('custom Base '+presence+' sidecar has zero optional demand',()=>{
  if(presence==='absent')fs.rmSync(file,{force:true});else put(presence==='valid'?valid:corrupt);
  const seen={api:0,world:0,open:0,read:0,consume:0},oldOpen=fs.openSync,oldRead=fs.readSync;
  const forbiddenApi=new Proxy({}, {get(){seen.api++;throw Error('Custom Base accessed optional API');}});
  const forbiddenWorld=new Proxy({}, {get(){seen.world++;throw Error('Custom Base accessed optional world');}});
  fs.openSync=(...args)=>{seen.open++;return oldOpen(...args);};fs.readSync=(...args)=>{seen.read++;return oldRead(...args);};
  try{
    assert.equal(D.prepareBaseAnnotations(forbiddenApi,forbiddenWorld,customInfo),false);
    assert.equal(D.readBaseAnnotations(forbiddenApi,customInfo,forbiddenWorld,load,selected,stops),null);
    assert.equal(D.withBaseAnnotationFile(customInfo,forbiddenWorld,()=>{seen.consume++;throw Error('Custom Base consumed sidecar');}),null);
  }finally{fs.openSync=oldOpen;fs.readSync=oldRead;}
  assert.deepEqual(seen,{api:0,world:0,open:0,read:0,consume:0});return{observed:seen};
});
